def icon(name):
    return f'<svg class="icon" aria-hidden="true"><use href="assets/icons.svg#{name}"></use></svg>'

def gas(local=False):
    specs=[]
    for i in range(28 if not local else 14):
        x=(i*37+9)%100
        size=[9,16,23,12,35,19,8,28,14,42,10,21][i%12]
        speed=39+(i*7)%25
        delay=-(i*11+13)%speed-speed
        drift=(i*13)%70-35
        alpha=.30+(i%5)*.07
        specs.append(f'<span class="gas-bubble" style="--x:{x}%;--size:{size}px;--speed:{speed}s;--delay:{delay}s;--drift:{drift}px;--alpha:{alpha:.2f}"></span>')
    return f'<div class="gas-background{" hero-gas" if local else ""}" aria-hidden="true">'+''.join(specs)+'</div>'

