products=[dict(re.findall(r"(\w+):'([^']*)'",row)) for row in re.findall(r'\{([^{}]+)\}',block)]

def cards(group=None,ids=None):
    selected=[p for p in products if p['group']==group] if group else [next(p for p in products if p['id']==i) for i in ids]
    result=''
    for p in selected:
        result+=f'''<article class="product-card"><button class="product-photo" type="button" data-detail="{p['id']}" aria-label="Ver detalhes de {p['name']}"><span class="product-tag">{p['filter']}</span><img src="assets/premium-products/{p['image']}" alt="Imagem ilustrativa de {p['name']}" loading="lazy" decoding="async" width="480" height="480"></button><div class="product-details"><h3 class="product-name"><button type="button" data-detail="{p['id']}">{p['name']}</button></h3><p class="product-volume">{p['volume']}</p><div class="product-card-bottom"><span class="product-price"><small>Valores</small>Sob consulta</span><button class="add-product" type="button" data-add="{p['id']}" aria-label="Adicionar {p['name']} à minha lista">{icon('plus')}</button></div><span class="product-quick-label">Toque na imagem para saber mais</span></div></article>'''
    return result

def document(page,title,description,body,group=None):
    canonical=ORIGIN+'/' if page=='index.html' else ORIGIN+'/'+page
    schema={'@context':'https://schema.org','@type':'WebSite','name':'Adega Mary','url':ORIGIN,'inLanguage':'pt-BR'}
    title,description=html.escape(title,quote=True),html.escape(description,quote=True)
    doc=f'''<!doctype html>
<html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#070708"><title>{title}</title><meta name="description" content="{description}"><meta property="og:title" content="{title}"><meta property="og:description" content="{description}"><meta property="og:type" content="website"><meta property="og:locale" content="pt_BR"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{ORIGIN}/assets/premium-hero.webp"><link rel="canonical" href="{canonical}"><link rel="icon" href="assets/favicon.svg?v=2" type="image/svg+xml"><link rel="stylesheet" href="assets/premium.css?v=2"><script src="assets/catalog.js?v=2" defer></script><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head>
<body data-design="premium"{f' data-catalog="{group}"' if group else ''}>{header(page)}<main id="conteudo">{body}</main>{footer()}{dialogs()}</body></html>'''
    (DOCS/page).write_text(doc,encoding='utf-8')

